namespace QualityReporter.CSharp.Duplication;
public static class DuplicateSymbolMapper
{
 public static void Map(IEnumerable<DuplicateGroup> groups,IEnumerable<FileResult> files){foreach(var f in files){f.Metrics.Duplication??=new();foreach(var s in f.Symbols)s.Metrics.Duplication??=new();}var lookup=files.ToDictionary(x=>x.Path.Replace('\\','/'));foreach(var g in groups)foreach(var fragment in g.Fragments){if(!lookup.TryGetValue(fragment.Path,out var file))continue;file.DuplicateGroups.Add(g.Id);var lines=Math.Max(0,fragment.EndLine-fragment.StartLine+1);file.Metrics.Duplication??=new();file.Metrics.Duplication.DuplicatedLines+=lines;file.Metrics.Duplication.DuplicateGroupCount++;foreach(var s in file.Symbols){var overlap=Math.Max(0,Math.Min(fragment.EndLine,s.Location.EndLine)-Math.Max(fragment.StartLine,s.Location.StartLine)+1);if(overlap==0)continue;s.DuplicateGroups.Add(g.Id);s.Metrics.Duplication??=new();s.Metrics.Duplication.DuplicatedLines+=overlap;s.Metrics.Duplication.DuplicateGroupCount++;}}foreach(var f in files){if(f.Metrics.Duplication is{} dm)dm.DuplicatedPercentage=f.Metrics.Loc==0?0:Math.Min(1,(double)dm.DuplicatedLines/f.Metrics.Loc);foreach(var s in f.Symbols)if(s.Metrics.Duplication is{} sm)sm.DuplicatedPercentage=s.Metrics.Loc==0?0:Math.Min(1,(double)sm.DuplicatedLines/s.Metrics.Loc);}}
}
